import { Injectable, signal, computed } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class CinemaStore {
  readonly selectedSeats = signal<string[]>([]);
  readonly seatCount = computed(() => this.selectedSeats().length);
  toggleSeat(seatId: string) {
    this.selectedSeats.update(seats => seats.includes(seatId) ? seats.filter(s => s !== seatId) : [...seats, seatId]);
  }
}

